package com.singtel.ruleengineservice;
import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import java.util.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.singtel.platformcommon.*;import java.security.Principal;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api/v1/rules") public class RuleController{private final RuleRepository repo;private final ObjectMapper json;private final Events events;public RuleController(RuleRepository r,ObjectMapper j,Events e){repo=r;json=j;events=e;}
 public record Create(@NotBlank @Size(max=120)String name,@NotNull RuleModel.Expression expression){} public record Simulation(@NotNull RuleModel.Expression expression,@NotNull Map<String,Object> facts){}
 public record View(UUID id,String name,int version,RuleModel.Expression expression,java.time.Instant publishedAt,String checksum){}
 private View view(RuleVersion r){try{return new View(r.id,r.name,r.version,json.readValue(r.expressionJson,RuleModel.Expression.class),r.publishedAt,r.checksum);}catch(Exception e){throw new IllegalStateException(e);}}
 @GetMapping @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public List<View> list(){return repo.findAll().stream().map(this::view).toList();}
 @PostMapping @ResponseStatus(org.springframework.http.HttpStatus.CREATED) @Transactional @PreAuthorize("hasAnyRole('MANAGER','ADMIN')")public View publish(@Valid @RequestBody Create input,Principal principal)throws Exception{RuleModel.validate(input.expression());var r=new RuleVersion();r.name=input.name();r.createdBy=principal.getName();r.expressionJson=json.writeValueAsString(input.expression());r.checksum=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(r.expressionJson.getBytes(StandardCharsets.UTF_8)));repo.save(r);events.append(r.id.toString(),"rule.published",Map.of("ruleVersionId",r.id,"checksum",r.checksum));return view(r);}
 @PostMapping("/validate") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')")public RuleModel.Decision validate(@Valid @RequestBody Create c){RuleModel.validate(c.expression());return new RuleModel.Decision(true,List.of("Expression is valid"));}
 @PostMapping("/simulate") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')")public RuleModel.Decision simulate(@Valid @RequestBody Simulation s){return RuleModel.evaluate(s.expression(),s.facts());}
 @PostMapping("/{id}/evaluate") @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public RuleModel.Decision evaluate(@PathVariable UUID id,@RequestBody Map<String,Object> facts){return RuleModel.evaluate(view(repo.findById(id).orElseThrow(DomainError::missing)).expression(),facts);}
 @GetMapping("/{id}") @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public View get(@PathVariable UUID id){return view(repo.findById(id).orElseThrow(DomainError::missing));}
}
